import { useMemo, useState } from 'react';
import {
  ACTIVATION_READINESS_STAGES,
  ACTIVATION_REVIEW_DECISION_ACTIONS,
  ACTIVATION_REVIEW_LOOP,
  ACTIVATION_REVIEW_NEXT_DECISIONS,
  ACTIVATION_REVIEW_SUMMARY,
  ACTIVATION_RETURN_REVIEW,
  ACTIVATION_SUCCESS_LANGUAGE,
} from '@promorang/shared';
import { ActivityIndicator, Pressable, ScrollView, StyleSheet, TextInput, type TextInputProps } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { router, useLocalSearchParams } from 'expo-router';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';

import { Text, View } from '@/components/Themed';
import { BorderRadius, Colors, Spacing, Typography } from '@/constants/DesignTokens';
import { supabase } from '@/lib/supabase';
import { useAuth } from '@/context/AuthContext';
import { useActivationOperations } from '@/hooks/useActivationOperations';

type Metadata = { scene?: string; outcome_detail?: string; content_needed?: string[]; collaborators?: string[]; participant_value?: string[]; social_return?: string; commercial_return?: string; what_counts?: string; funder_contribution?: string };
type MomentOption = { id: string; title: string; location: string; starts_at?: string; created_at?: string };
const stages = ACTIVATION_READINESS_STAGES.slice(0, 5);
const workspaceFocuses = [
  { id: 'shape', label: 'Shape', icon: 'calendar' },
  { id: 'team', label: 'Gather', icon: 'people' },
  { id: 'value', label: 'Fund + open', icon: 'diamond' },
  { id: 'review', label: 'Learn', icon: 'sparkles' },
] as const;
type WorkspaceFocus = (typeof workspaceFocuses)[number]['id'];
type EditorId = 'invite' | 'content' | 'contribution' | 'access' | 'payout' | 'review';

export default function ActivationDetailScreen() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const queryClient = useQueryClient();
  const { user } = useAuth();
  const [showMoments, setShowMoments] = useState(false);
  const [showScenes, setShowScenes] = useState(false);
  const [secureAmount, setSecureAmount] = useState('');
  const [fundingGoalDraft, setFundingGoalDraft] = useState('');
  const [workspaceFocus, setWorkspaceFocus] = useState<WorkspaceFocus>('shape');
  const [editor, setEditor] = useState<EditorId | null>(null);
  const [inviteForm, setInviteForm] = useState({ userId: '', role: 'creator', responsibility: '' });
  const [contentForm, setContentForm] = useState({ phase: 'before', title: '', direction: '' });
  const [contributionForm, setContributionForm] = useState({ type: 'service', description: '', amount: '' });
  const [accessForm, setAccessForm] = useState({ name: '', description: '', type: 'free', price: '', capacity: '', eligibility: '', reward: '' });
  const [payoutForm, setPayoutForm] = useState({ collaboratorId: '', purpose: '', amount: '', condition: '' });
  const [returnForm, setReturnForm] = useState({ showed: '', returned: '', stories: '', collaborations: '', grossValue: '', human: '', commercial: '', content: '', gems: '', participantValue: '', sceneLearning: '', nextDecision: 'improve', nextDecisionNote: '' });
  const { data: activation, isLoading } = useQuery({ queryKey: ['activation', id], queryFn: async () => { const { data, error } = await supabase.from('proposals').select('*').eq('id', id).single(); if (error) throw error; return data; }, enabled: Boolean(id) });
  const { data: moments = [] } = useQuery({ queryKey: ['activation-moment-options', user?.id], queryFn: async () => { if (!user) return []; const { data, error } = await supabase.from('moments').select('*').eq('host_id', user.id).order('created_at', { ascending: false }).limit(10); if (error) throw error; return (data || []) as MomentOption[]; }, enabled: Boolean(user) });
  const operations = useActivationOperations(id);
  const metadata = useMemo(() => (activation?.metadata || {}) as Metadata, [activation?.metadata]);
  const selectedMoment = moments.find((moment) => moment.id === activation?.target_moment_id);
  const readiness = useMemo(() => [Boolean(metadata.outcome_detail && (activation?.scene_id || metadata.scene)), Boolean(activation?.target_moment_id), Boolean((operations.operations.data?.content.length || metadata.content_needed?.length) && (operations.operations.data?.collaborators.length || metadata.collaborators?.length)), Boolean(metadata.participant_value?.length && metadata.social_return && metadata.commercial_return), ['funded', 'live', 'completed', 'reviewed'].includes(activation?.lifecycle_state || '')], [activation, metadata, operations.operations.data]);
  const nextStage = readiness.findIndex((ready) => !ready);
  const recommendedFocus: WorkspaceFocus = nextStage < 0 ? 'review' : nextStage <= 1 ? 'shape' : nextStage === 2 ? 'team' : 'value';
  const selectedScene = operations.scenes.data?.find((scene) => scene.id === activation?.scene_id);
  const myInvitation = operations.operations.data?.collaborators.find((person) => person.invited_user_id === user?.id && ['invited', 'viewed', 'changes_requested'].includes(person.status));
  const fundingGoal = Number(activation?.funding_goal_gems || activation?.budget || 0);
  const walletGems = Number(operations.operations.data?.wallet?.gems || 0);
  const reserve = operations.operations.data?.reserve;
  const securedGems = Number(reserve?.secured_gems || 0);
  const releasedGems = Number(reserve?.released_gems || 0);
  const refundedGems = Number(reserve?.refunded_gems || 0);
  const usableReserve = Math.max(securedGems - releasedGems - refundedGems, 0);
  const saveFundingGoal = useMutation({ mutationFn: async () => { const amount = Number(fundingGoalDraft); if (!amount || amount <= 0) throw new Error('Enter a Gem funding goal greater than zero.'); const { error } = await supabase.from('proposals').update({ funding_goal_gems: amount }).eq('id', id); if (error) throw error; }, onSuccess: async () => { setFundingGoalDraft(''); await queryClient.invalidateQueries({ queryKey: ['activation', id] }); } });
  const latestOutcome = operations.operations.data?.outcomes?.[0];
  const decisionAction = latestOutcome?.next_decision ? ACTIVATION_REVIEW_DECISION_ACTIONS[latestOutcome.next_decision as keyof typeof ACTIVATION_REVIEW_DECISION_ACTIONS] : null;
  const openDecision = () => {
    if (latestOutcome?.next_decision === 'repeat') return router.push('/create-proposal');
    if (latestOutcome?.next_decision === 'invite') return setWorkspaceFocus('team');
    if (latestOutcome?.next_decision === 'fund') return setWorkspaceFocus('value');
    if (latestOutcome?.next_decision === 'improve') return setWorkspaceFocus('shape');
    setWorkspaceFocus('review');
  };
  const reviewLoop = ACTIVATION_REVIEW_LOOP.map((item) => {
    const value = item.id === 'people' && latestOutcome
      ? `${Number(latestOutcome.people_showed_up).toLocaleString()} showed · ${Number(latestOutcome.people_returned).toLocaleString()} returned`
      : item.id === 'content' && latestOutcome
        ? `${Number(latestOutcome.stories_created).toLocaleString()} stories created`
        : item.id === 'content' && metadata.content_needed?.length
          ? metadata.content_needed.join(' · ')
          : item.id === 'contribution' && latestOutcome
            ? `${Number(latestOutcome.collaborations_opened).toLocaleString()} doors opened`
            : item.id === 'contribution' && metadata.what_counts
              ? metadata.what_counts
              : item.id === 'value'
                ? `${releasedGems.toLocaleString()} Gems released · ${usableReserve.toLocaleString()} held`
                : item.id === 'commercial' && (latestOutcome?.commercial_return_summary || metadata.commercial_return)
                  ? latestOutcome?.commercial_return_summary || metadata.commercial_return
                  : item.id === 'scene' && (latestOutcome?.scene_learning_summary || latestOutcome?.human_return_summary || metadata.social_return)
                    ? latestOutcome?.scene_learning_summary || latestOutcome?.human_return_summary || metadata.social_return
                    : item.id === 'next' && latestOutcome
                      ? `${latestOutcome.next_decision ? `${latestOutcome.next_decision}: ` : ''}${latestOutcome.next_decision_note || `Use this return to shape the next Moment in ${metadata.scene || 'the Scene'}.`}`
                      : item.empty;
    return { ...item, value };
  });

  if (isLoading) return <View style={styles.loading}><ActivityIndicator color={Colors.primary} /></View>;
  if (!activation) return <View style={styles.loading}><Text style={styles.muted}>Activation not found.</Text></View>;
  return <View style={styles.screen}>
    <View style={styles.header}><Pressable onPress={() => router.back()} style={styles.iconButton}><Ionicons name="arrow-back" size={20} color={Colors.white} /></Pressable><View style={styles.headerCopy}><Text style={styles.eyebrow}>ACTIVATION ROOM</Text><Text style={styles.headerTitle} numberOfLines={1}>{activation.title}</Text></View></View>
    <ScrollView contentContainerStyle={styles.content} showsVerticalScrollIndicator={false}>
      <Text style={styles.scene}>{String(metadata.scene || 'SCENE TO BE CHOSEN').toUpperCase()}</Text><Text style={styles.title}>{activation.title}</Text><Text style={styles.subtitle}>{String(metadata.outcome_detail || activation.description || '')}</Text>
      <View style={styles.rail}>{stages.map((stage, index) => <View key={stage.id} style={styles.railItem}><View style={[styles.dot, readiness[index] && styles.dotReady]}>{readiness[index] ? <Ionicons name="checkmark" size={11} color={Colors.black} /> : <Text style={styles.dotText}>{index + 1}</Text>}</View><Text style={[styles.railText, readiness[index] && styles.railTextReady]}>{stage.label}</Text></View>)}</View>
      <Pressable accessibilityRole="button" onPress={() => setWorkspaceFocus(recommendedFocus)} style={styles.currentMove}><View style={styles.currentMoveIcon}><Ionicons name="arrow-forward" size={18} color={Colors.black} /></View><View style={styles.flex}><Text style={styles.currentMoveLabel}>YOUR CURRENT MOVE</Text><Text style={styles.currentMoveTitle}>{nextStage < 0 ? 'Review the shared return' : stages[nextStage].label}</Text><Text style={styles.currentMoveText}>{nextStage < 0 ? 'Decide whether to repeat, improve, invite, fund, or close.' : stages[nextStage].detail}</Text></View></Pressable>
      {myInvitation && <View style={styles.invitation}><Text style={styles.returnLabel}>YOU’RE INVITED AS {myInvitation.role.replaceAll('_', ' ').toUpperCase()}</Text><Text style={styles.invitationTitle}>{myInvitation.responsibility || 'Help bring this activation alive.'}</Text><View style={styles.responseRow}><Pressable onPress={() => operations.respond.mutate({ id: myInvitation.id, response: 'accepted' })} style={styles.responsePrimary}><Text style={styles.primaryText}>I’m in</Text></Pressable><Pressable onPress={() => operations.respond.mutate({ id: myInvitation.id, response: 'changes_requested' })} style={styles.responseSecondary}><Text style={styles.responseText}>Align first</Text></Pressable><Pressable onPress={() => operations.respond.mutate({ id: myInvitation.id, response: 'declined' })} style={styles.responseSecondary}><Text style={styles.responseText}>Not now</Text></Pressable></View></View>}

      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.focusRail}>{workspaceFocuses.map((item) => <Pressable key={item.id} accessibilityRole="tab" accessibilityState={{ selected: workspaceFocus === item.id }} onPress={() => setWorkspaceFocus(item.id)} style={[styles.focusPill, workspaceFocus === item.id && styles.focusPillActive]}><Ionicons name={item.icon} size={15} color={workspaceFocus === item.id ? Colors.black : Colors.primary} /><Text style={[styles.focusText, workspaceFocus === item.id && styles.focusTextActive]}>{item.label}</Text></Pressable>)}</ScrollView>

      {workspaceFocus === 'shape' && <>
      <Section icon="calendar" eyebrow="SCENE + MOMENT" title="Give the Scene a reason to gather now"><Text style={styles.body}>The Scene carries the relationships. The Moment is where people meet, participate, create, and contribute.</Text><View style={styles.pickerRow}><Pressable onPress={() => setShowScenes(!showScenes)} style={styles.picker}><Text style={styles.selectedLabel}>SCENE</Text><Text style={styles.pickerText}>{selectedScene?.title || metadata.scene || 'Choose a Scene'}</Text></Pressable><Pressable onPress={() => setShowMoments(!showMoments)} style={styles.picker}><Text style={styles.selectedLabel}>MOMENT</Text><Text style={styles.pickerText}>{selectedMoment?.title || 'Choose yours'}</Text></Pressable></View>{showScenes && <View style={styles.options}>{operations.scenes.data?.map((scene) => <Pressable key={scene.id} onPress={() => { operations.linkScene.mutate(scene.id); setShowScenes(false); }} style={styles.option}><View style={styles.flex}><Text style={styles.optionTitle}>{scene.title}</Text><Text style={styles.optionMeta}>{scene.city || 'Promorang Scene'}</Text></View><Ionicons name="chevron-forward" size={16} color={Colors.primary} /></Pressable>)}</View>}{showMoments && <View style={styles.options}>{moments.map((moment) => <Pressable key={moment.id} onPress={() => { operations.linkMoment.mutate(moment.id); setShowMoments(false); }} style={styles.option}><View style={styles.flex}><Text style={styles.optionTitle}>{moment.title}</Text><Text style={styles.optionMeta}>{moment.location}</Text></View><Ionicons name="chevron-forward" size={16} color={Colors.primary} /></Pressable>)}</View>}</Section>
      <Section icon="videocam" eyebrow="CONTENT DIRECTION" title="Build the story around the Moment"><Chips values={metadata.content_needed} empty="Choose how the story moves before, during, and after." /><Text style={styles.bodyAfter}>Content creates desire, helps people participate, and carries the Scene into what comes next.</Text></Section>
      </>}
      {workspaceFocus === 'team' && <>
      <Section icon="people" eyebrow="THE HUMAN NETWORK" title="Put the right people around it">{operations.operations.data?.collaborators.length ? operations.operations.data.collaborators.map((person) => <View key={person.id} style={styles.operationRow}><View style={styles.flex}><Text style={styles.optionTitle}>{person.display_name || 'Collaborator'}</Text><Text style={styles.optionMeta}>{person.role.replaceAll('_', ' ')} · {person.responsibility}</Text></View><Text style={styles.operationStatus}>{person.status.replaceAll('_', ' ')}</Text></View>) : <Chips values={metadata.collaborators} empty="Hosts, creators, venues, merchants, and brands can each power a different part." />}</Section>
      <Section icon="videocam" eyebrow="STORY RESPONSIBILITIES" title="See who owns what">{operations.operations.data?.content.length ? operations.operations.data.content.map((item) => <View key={item.id} style={styles.operationRow}><View style={styles.flex}><Text style={styles.optionTitle}>{item.title}</Text><Text style={styles.optionMeta}>{item.phase} · {item.direction}</Text></View><Text style={styles.operationStatus}>{item.status}</Text></View>) : <Text style={styles.body}>Assign the invitation, live story, or after-story that someone should own.</Text>}</Section>
      <Section icon="gift" eyebrow="CONTRIBUTIONS" title="See what partners put into the room">{operations.operations.data?.contributions.length ? operations.operations.data.contributions.map((item) => <View key={item.id} style={styles.operationRow}><View style={styles.flex}><Text style={styles.optionTitle}>{item.contribution_type}</Text><Text style={styles.optionMeta}>{item.description}</Text></View><Text style={styles.operationStatus}>{item.amount ? `${item.currency === 'usd' ? 'Gems' : item.currency} ${item.amount}` : item.status}</Text></View>) : <Text style={styles.body}>Gems, place, product, access, media, and services will appear here.</Text>}</Section>
      <MoveTray actions={[{ id: 'invite', label: 'Invite someone', icon: 'person-add' }, { id: 'content', label: 'Assign story', icon: 'videocam' }, { id: 'contribution', label: 'Add contribution', icon: 'gift' }]} active={editor} onChoose={(id) => setEditor(editor === id ? null : id)} />
      {editor === 'invite' && <EditorCard eyebrow="OPEN AN INVITATION" title="Give someone a meaningful role"><ChoiceRail values={(operations.people.data || []).map((person) => ({ id: person.user_id, label: person.full_name || 'Promorang member' }))} selected={inviteForm.userId} onSelect={(userId) => setInviteForm((current) => ({ ...current, userId }))} /><ChoiceRail values={['host', 'creator', 'venue', 'merchant', 'brand', 'scene_lead'].map((role) => ({ id: role, label: role.replaceAll('_', ' ') }))} selected={inviteForm.role} onSelect={(role) => setInviteForm((current) => ({ ...current, role }))} /><MobileField label="WHAT ARE THEY BEING INVITED TO MAKE POSSIBLE?" value={inviteForm.responsibility} onChangeText={(responsibility) => setInviteForm((current) => ({ ...current, responsibility }))} multiline /><FormAction label="Open invitation" disabled={!inviteForm.userId || !inviteForm.responsibility.trim()} pending={operations.invite.isPending} onPress={() => { const person = operations.people.data?.find((item) => item.user_id === inviteForm.userId); if (person) operations.invite.mutate({ userId: person.user_id, name: person.full_name || 'Collaborator', role: inviteForm.role, responsibility: inviteForm.responsibility }, { onSuccess: () => { setEditor(null); setInviteForm({ userId: '', role: 'creator', responsibility: '' }); } }); }} /></EditorCard>}
      {editor === 'content' && <EditorCard eyebrow="STORY RESPONSIBILITY" title="Turn direction into owned work"><ChoiceRail values={['invite', 'before', 'live', 'after', 'evergreen'].map((phase) => ({ id: phase, label: phase }))} selected={contentForm.phase} onSelect={(phase) => setContentForm((current) => ({ ...current, phase }))} /><MobileField label="RESPONSIBILITY" value={contentForm.title} onChangeText={(title) => setContentForm((current) => ({ ...current, title }))} placeholder="e.g. Creator invitation story" /><MobileField label="WHAT SHOULD IT HELP PEOPLE FEEL OR DO?" value={contentForm.direction} onChangeText={(direction) => setContentForm((current) => ({ ...current, direction }))} multiline /><FormAction label="Assign this story" disabled={!contentForm.title.trim() || !contentForm.direction.trim()} pending={operations.addContent.isPending} onPress={() => operations.addContent.mutate(contentForm, { onSuccess: () => { setEditor(null); setContentForm({ phase: 'before', title: '', direction: '' }); } })} /></EditorCard>}
      {editor === 'contribution' && <EditorCard eyebrow="PARTNER CONTRIBUTION" title="Show what enters the room"><ChoiceRail values={['venue', 'product', 'service', 'access', 'media', 'talent', 'reward', 'transport'].map((type) => ({ id: type, label: type }))} selected={contributionForm.type} onSelect={(type) => setContributionForm((current) => ({ ...current, type }))} /><MobileField label="WHAT IS BEING CONTRIBUTED?" value={contributionForm.description} onChangeText={(description) => setContributionForm((current) => ({ ...current, description }))} multiline /><MobileField label="VALUE IN GEMS, IF APPLICABLE" value={contributionForm.amount} onChangeText={(amount) => setContributionForm((current) => ({ ...current, amount }))} keyboardType="numeric" /><FormAction label="Record contribution" disabled={!contributionForm.description.trim()} pending={operations.addContribution.isPending} onPress={() => operations.addContribution.mutate({ type: contributionForm.type, description: contributionForm.description, amount: Number(contributionForm.amount) || undefined }, { onSuccess: () => { setEditor(null); setContributionForm({ type: 'service', description: '', amount: '' }); } })} /></EditorCard>}
      </>}
      {workspaceFocus === 'value' && <>
      <Section icon="ticket" eyebrow="ACCESS + VALUE" title="Choose how you enter the Moment">{operations.operations.data?.access.length ? operations.operations.data.access.map((tier) => { const pass = operations.operations.data?.passes.find((item) => item.tier_id === tier.id); const canBuy = walletGems >= Number(tier.price || 0); return <View key={tier.id} style={styles.accessCard}><View style={styles.operationRow}><View style={styles.flex}><Text style={styles.optionTitle}>{tier.name}</Text><Text style={styles.optionMeta}>{tier.access_type} · {tier.price ? `${tier.price} Gems` : 'Free'} · {tier.capacity ? `${tier.issued_count}/${tier.capacity}` : `${tier.issued_count} joined`}</Text></View></View><Text style={styles.body}>{tier.description}</Text>{tier.price > 0 && <Text style={styles.paidNote}>US${Number(tier.price).toLocaleString()} platform value</Text>}{tier.reward_summary && <Text style={styles.accessReward}>OPENS: {tier.reward_summary}</Text>}{pass ? <View style={styles.pass}><Text style={styles.selectedLabel}>YOUR ACCESS</Text><Text style={styles.passCode}>{pass.pass_code}</Text></View> : tier.access_type === 'free' && tier.status === 'open' ? <Pressable onPress={() => operations.claimAccess.mutate(tier.id)} style={styles.primary}><Text style={styles.primaryText}>Claim access</Text><Ionicons name="arrow-forward" size={16} color={Colors.black} /></Pressable> : tier.access_type === 'paid' ? <Pressable disabled={!canBuy || operations.purchaseAccess.isPending || tier.status !== 'open'} onPress={() => operations.purchaseAccess.mutate(tier.id)} style={[styles.primary, (!canBuy || operations.purchaseAccess.isPending || tier.status !== 'open') && styles.disabled]}><Text style={styles.primaryText}>{canBuy ? 'Use Gems for access' : 'Need more Gems'}</Text><Ionicons name="arrow-forward" size={16} color={Colors.black} /></Pressable> : null}</View>; }) : <Text style={styles.body}>Access options will appear here when the host opens them.</Text>}</Section>
      <Section icon="diamond" eyebrow="PAYOUT PROMISES" title="Know what is owed and why">{operations.operations.data?.payouts.length ? operations.operations.data.payouts.map((item) => <View key={item.id} style={styles.operationRow}><View style={styles.flex}><Text style={styles.optionTitle}>{item.purpose}</Text><Text style={styles.optionMeta}>Released when: {item.release_condition}</Text></View><View><Text style={styles.payoutAmount}>{Number(item.amount).toLocaleString()} Gems</Text><Text style={styles.operationStatus}>{item.status}</Text>{item.status === 'earned' && <Pressable disabled={usableReserve < Number(item.amount) || operations.releasePayout.isPending} onPress={() => operations.releasePayout.mutate(item.id)}><Text style={[styles.actionText, usableReserve < Number(item.amount) && styles.actionDisabled]}>RELEASE</Text></Pressable>}</View></View>) : <Text style={styles.body}>Agreed creator, host, and collaborator Gem payouts will appear here.</Text>}</Section>
      <MoveTray actions={[{ id: 'access', label: 'Open access', icon: 'ticket' }, { id: 'payout', label: 'Promise payout', icon: 'diamond' }]} active={editor} onChoose={(id) => setEditor(editor === id ? null : id)} />
      {editor === 'access' && <EditorCard eyebrow="ACCESS PATH" title="Give people a clear way in"><ChoiceRail values={['free', 'paid', 'invite', 'earned', 'reward'].map((type) => ({ id: type, label: type }))} selected={accessForm.type} onSelect={(type) => setAccessForm((current) => ({ ...current, type, price: type === 'paid' ? current.price : '' }))} /><MobileField label="ACCESS NAME" value={accessForm.name} onChangeText={(name) => setAccessForm((current) => ({ ...current, name }))} /><MobileField label="WHAT KIND OF EXPERIENCE IS THIS?" value={accessForm.description} onChangeText={(description) => setAccessForm((current) => ({ ...current, description }))} multiline />{accessForm.type === 'paid' && <MobileField label="PRICE IN GEMS · 1 GEM = US$1" value={accessForm.price} onChangeText={(price) => setAccessForm((current) => ({ ...current, price }))} keyboardType="numeric" />}<MobileField label="CAPACITY" value={accessForm.capacity} onChangeText={(capacity) => setAccessForm((current) => ({ ...current, capacity }))} keyboardType="numeric" /><MobileField label="WHO IS THIS FOR?" value={accessForm.eligibility} onChangeText={(eligibility) => setAccessForm((current) => ({ ...current, eligibility }))} /><MobileField label="WHAT ELSE CAN IT OPEN?" value={accessForm.reward} onChangeText={(reward) => setAccessForm((current) => ({ ...current, reward }))} /><FormAction label="Open this access" disabled={!activation.target_moment_id || !accessForm.name.trim() || (accessForm.type === 'paid' && !Number(accessForm.price))} pending={operations.addAccess.isPending} onPress={() => operations.addAccess.mutate({ momentId: activation.target_moment_id || undefined, name: accessForm.name, description: accessForm.description, type: accessForm.type, price: Number(accessForm.price) || 0, capacity: Number(accessForm.capacity) || undefined, eligibility: accessForm.eligibility, reward: accessForm.reward }, { onSuccess: () => setEditor(null) })} /></EditorCard>}
      {editor === 'payout' && <EditorCard eyebrow="GEM PAYOUT PROMISE" title="Make compensation clear before the work"><ChoiceRail values={(operations.operations.data?.collaborators || []).filter((person) => person.status === 'accepted' && person.invited_user_id).map((person) => ({ id: person.id, label: person.display_name || person.role }))} selected={payoutForm.collaboratorId} onSelect={(collaboratorId) => setPayoutForm((current) => ({ ...current, collaboratorId }))} /><MobileField label="WHAT IS THIS PAYMENT FOR?" value={payoutForm.purpose} onChangeText={(purpose) => setPayoutForm((current) => ({ ...current, purpose }))} /><MobileField label="AMOUNT IN GEMS" value={payoutForm.amount} onChangeText={(amount) => setPayoutForm((current) => ({ ...current, amount }))} keyboardType="numeric" /><MobileField label="WHAT MUST BE COMPLETE BEFORE RELEASE?" value={payoutForm.condition} onChangeText={(condition) => setPayoutForm((current) => ({ ...current, condition }))} multiline /><FormAction label="Record payout promise" disabled={!payoutForm.collaboratorId || !payoutForm.purpose.trim() || !Number(payoutForm.amount) || !payoutForm.condition.trim()} pending={operations.addPayout.isPending} onPress={() => { const collaborator = operations.operations.data?.collaborators.find((person) => person.id === payoutForm.collaboratorId); if (collaborator?.invited_user_id) operations.addPayout.mutate({ momentId: activation.target_moment_id || undefined, collaboratorId: collaborator.id, recipientId: collaborator.invited_user_id, purpose: payoutForm.purpose, amount: Number(payoutForm.amount), condition: payoutForm.condition }, { onSuccess: () => setEditor(null) }); }} /></EditorCard>}
      </>}
      {workspaceFocus === 'review' && <>
      <Section icon="heart" eyebrow="SHARED RETURN" title="Make success valuable from every side"><Return label="FOR PARTICIPANTS" value={metadata.social_return || metadata.participant_value?.join(' · ')} /><Return label="FOR VENUES, MERCHANTS + BRANDS" value={metadata.commercial_return} /><Text style={styles.bodyAfter}>{ACTIVATION_SUCCESS_LANGUAGE.sharedReturn}</Text></Section>
      <Section icon="sparkles" eyebrow={ACTIVATION_REVIEW_SUMMARY.title.toUpperCase()} title={latestOutcome ? 'The return loop is forming' : ACTIVATION_RETURN_REVIEW.emptyTitle}><Text style={styles.body}>{ACTIVATION_REVIEW_SUMMARY.body}</Text><View style={styles.reviewLoop}>{reviewLoop.map((item) => <ReviewLoopCard key={item.id} label={item.label} question={item.question} value={item.value} />)}</View></Section>
      {latestOutcome && <Section icon="document-text" eyebrow="ACTIVATION REVIEW REPORT" title={`What ${metadata.scene || 'the Scene'} should do next`}><Text style={styles.outcomeHuman}>{latestOutcome.human_return_summary || 'The human return still needs to be captured.'}</Text><Text style={styles.bodyAfter}>{latestOutcome.commercial_return_summary || 'Commercial return should connect to visits, sales, redemptions, demand, or partner value.'}</Text><View style={styles.reportGrid}><MiniResult value={latestOutcome.people_showed_up} label="Showed" /><MiniResult value={latestOutcome.stories_created} label="Stories" /><MiniResult value={latestOutcome.collaborations_opened} label="Doors" /></View><ReviewSignal label="Participant value" value={latestOutcome.participant_value_summary} /><ReviewSignal label="Content return" value={latestOutcome.content_return_summary} /><ReviewSignal label="Gems moved" value={latestOutcome.gems_return_summary} /><ReviewSignal label="Scene learning" value={latestOutcome.scene_learning_summary} />{decisionAction && <Pressable accessibilityRole="button" onPress={openDecision} style={styles.decisionBox}><Text style={styles.reviewLabel}>NEXT DECISION · {latestOutcome.next_decision}</Text><Text style={styles.reviewQuestion}>{decisionAction.title}</Text><Text style={styles.reviewValue}>{latestOutcome.next_decision_note || decisionAction.detail}</Text><View style={styles.decisionAction}><Text style={styles.decisionActionText}>{decisionAction.cta}</Text><Ionicons name="arrow-forward" size={14} color={Colors.primary} /></View></Pressable>}</Section>}
      {operations.operations.data?.outcomes.length ? operations.operations.data.outcomes.map((outcome) => <Section key={outcome.id} icon="sparkles" eyebrow={ACTIVATION_RETURN_REVIEW.eyebrow.toUpperCase()} title="The return everyone can see"><View style={styles.resultGrid}><MiniResult value={outcome.people_showed_up} label="Showed" /><MiniResult value={outcome.people_returned} label="Returned" /><MiniResult value={outcome.stories_created} label="Stories" /><MiniResult value={outcome.collaborations_opened} label="Doors" /></View><Text style={styles.outcomeHuman}>{outcome.human_return_summary}</Text><Text style={styles.bodyAfter}>{outcome.commercial_return_summary}</Text>{outcome.participant_value_summary && <Text style={styles.bodyAfter}>Participant value: {outcome.participant_value_summary}</Text>}{outcome.content_return_summary && <Text style={styles.bodyAfter}>Content: {outcome.content_return_summary}</Text>}{outcome.gems_return_summary && <Text style={styles.bodyAfter}>Gems: {outcome.gems_return_summary}</Text>}{outcome.scene_learning_summary && <Text style={styles.bodyAfter}>Scene learning: {outcome.scene_learning_summary}</Text>}{outcome.next_decision && <Text style={styles.decisionCallout}>NEXT: {outcome.next_decision}{outcome.next_decision_note ? ` · ${outcome.next_decision_note}` : ''}</Text>}</Section>) : <Section icon="sparkles" eyebrow={ACTIVATION_RETURN_REVIEW.eyebrow.toUpperCase()} title={ACTIVATION_RETURN_REVIEW.emptyTitle}><Text style={styles.body}>{ACTIVATION_RETURN_REVIEW.emptyBody}</Text></Section>}
      {['completed', 'reviewed'].includes(activation.lifecycle_state || '') && <><MoveTray actions={[{ id: 'review', label: latestOutcome ? 'Add new review' : 'Record return', icon: 'document-text' }]} active={editor} onChoose={(id) => setEditor(editor === id ? null : id)} />{editor === 'review' && <EditorCard eyebrow="SHARED RETURN" title="What changed because this happened?"><View style={styles.metricInputs}><MobileField compact label="SHOWED" value={returnForm.showed} onChangeText={(showed) => setReturnForm((current) => ({ ...current, showed }))} keyboardType="numeric" /><MobileField compact label="RETURNED" value={returnForm.returned} onChangeText={(returned) => setReturnForm((current) => ({ ...current, returned }))} keyboardType="numeric" /><MobileField compact label="STORIES" value={returnForm.stories} onChangeText={(stories) => setReturnForm((current) => ({ ...current, stories }))} keyboardType="numeric" /><MobileField compact label="DOORS" value={returnForm.collaborations} onChangeText={(collaborations) => setReturnForm((current) => ({ ...current, collaborations }))} keyboardType="numeric" /></View><MobileField label="GEMS OR COMMERCIAL VALUE MOVED" value={returnForm.grossValue} onChangeText={(grossValue) => setReturnForm((current) => ({ ...current, grossValue }))} keyboardType="numeric" /><MobileField label="WHAT CHANGED FOR PEOPLE?" value={returnForm.human} onChangeText={(human) => setReturnForm((current) => ({ ...current, human }))} multiline /><MobileField label="WHAT CHANGED FOR PARTNERS?" value={returnForm.commercial} onChangeText={(commercial) => setReturnForm((current) => ({ ...current, commercial }))} multiline /><MobileField label="WHAT CONTENT BECAME USEFUL?" value={returnForm.content} onChangeText={(content) => setReturnForm((current) => ({ ...current, content }))} multiline /><MobileField label="WHAT VALUE DID PARTICIPANTS LEAVE WITH?" value={returnForm.participantValue} onChangeText={(participantValue) => setReturnForm((current) => ({ ...current, participantValue }))} multiline /><MobileField label="WHAT GEMS WERE SECURED, EARNED OR RELEASED?" value={returnForm.gems} onChangeText={(gems) => setReturnForm((current) => ({ ...current, gems }))} multiline /><MobileField label="WHAT DID THE SCENE LEARN?" value={returnForm.sceneLearning} onChangeText={(sceneLearning) => setReturnForm((current) => ({ ...current, sceneLearning }))} multiline /><ChoiceRail values={ACTIVATION_REVIEW_NEXT_DECISIONS.map((decision) => ({ id: decision.id, label: decision.label }))} selected={returnForm.nextDecision} onSelect={(nextDecision) => setReturnForm((current) => ({ ...current, nextDecision }))} /><MobileField label="WHY IS THIS THE NEXT MOVE?" value={returnForm.nextDecisionNote} onChangeText={(nextDecisionNote) => setReturnForm((current) => ({ ...current, nextDecisionNote }))} multiline /><FormAction label="Record shared return" disabled={!returnForm.human.trim() || !returnForm.commercial.trim()} pending={operations.recordOutcome.isPending} onPress={() => operations.recordOutcome.mutate({ sceneId: activation.scene_id || undefined, momentId: activation.target_moment_id || undefined, showed: Number(returnForm.showed) || 0, returned: Number(returnForm.returned) || 0, stories: Number(returnForm.stories) || 0, collaborations: Number(returnForm.collaborations) || 0, grossValue: Number(returnForm.grossValue) || 0, human: returnForm.human, commercial: returnForm.commercial, content: returnForm.content, gems: returnForm.gems, participantValue: returnForm.participantValue, sceneLearning: returnForm.sceneLearning, nextDecision: returnForm.nextDecision, nextDecisionNote: returnForm.nextDecisionNote }, { onSuccess: () => setEditor(null) })} /></EditorCard>}</>}
      </>}
      <View style={styles.launch}><Text style={styles.launchLabel}>BRING IT ALIVE · {(activation.lifecycle_state || 'shaping').replaceAll('_', ' ').toUpperCase()}</Text><Info label="YOUR GEM WALLET" value={`${walletGems.toLocaleString()} Gems available`} /><Info label="GEM FUNDING GOAL" value={fundingGoal ? `${fundingGoal.toLocaleString()} Gems · US$${fundingGoal.toLocaleString()} value` : 'Not agreed yet'} />{!fundingGoal && <View style={styles.secureBox}><Text style={styles.returnLabel}>SET THE GEM RESERVE</Text><Text style={styles.paidNote}>Choose the total amount that must be secured before this activation can become funded.</Text><View style={styles.secureRow}><TextInput keyboardType="numeric" value={fundingGoalDraft} onChangeText={setFundingGoalDraft} placeholder="Funding goal" placeholderTextColor={Colors.gray[600]} style={styles.input} /><Pressable disabled={!Number(fundingGoalDraft) || saveFundingGoal.isPending} onPress={() => saveFundingGoal.mutate()} style={[styles.secureButton, (!Number(fundingGoalDraft) || saveFundingGoal.isPending) && styles.disabled]}><Text style={styles.primaryText}>Set goal</Text></Pressable></View></View>}<Info label="GEMS SECURED" value={`${securedGems.toLocaleString()} Gems`} /><Info label="STILL HELD FOR RELEASE" value={`${usableReserve.toLocaleString()} Gems`} /><Info label="PARTNER CONTRIBUTION" value={metadata.funder_contribution || 'Gems, place, product, access, or reach'} />{fundingGoal > 0 && ['aligned', 'funding', 'funded'].includes(activation.lifecycle_state || '') && <View style={styles.secureBox}><Text style={styles.returnLabel}>SECURE GEMS</Text><View style={styles.secureRow}><TextInput keyboardType="numeric" value={secureAmount} onChangeText={setSecureAmount} placeholder="Amount" placeholderTextColor={Colors.gray[600]} style={styles.input} /><Pressable disabled={!Number(secureAmount) || Number(secureAmount) > walletGems || operations.secureGems.isPending} onPress={() => operations.secureGems.mutate(Number(secureAmount), { onSuccess: () => setSecureAmount('') })} style={[styles.secureButton, (!Number(secureAmount) || Number(secureAmount) > walletGems || operations.secureGems.isPending) && styles.disabled]}><Text style={styles.primaryText}>Secure</Text></Pressable></View><Text style={styles.paidNote}>1 Gem = US$1. Secured Gems stay with this activation until release or refund.</Text></View>}{operations.operations.data?.reservations.slice(0, 3).map((reservation) => <View key={reservation.id} style={styles.reservation}><View style={styles.flex}><Text style={styles.optionTitle}>{Number(reservation.amount_gems).toLocaleString()} Gems</Text><Text style={styles.optionMeta}>{reservation.purpose.replaceAll('_', ' ')} · {reservation.status}</Text></View>{['secured', 'partially_released', 'partially_refunded', 'disputed'].includes(reservation.status) && <Pressable disabled={operations.refundReservation.isPending} onPress={() => operations.refundReservation.mutate(reservation.id)}><Text style={styles.actionText}>REFUND</Text></Pressable>}</View>)}<MobileLifecycle state={activation.lifecycle_state || 'shaping'} ready={readiness.slice(0, 4).every(Boolean)} fundingReady={fundingGoal > 0 && securedGems >= fundingGoal} pending={operations.move.isPending} onMove={(state) => operations.move.mutate(state)} /></View>
      <View style={{ height: 35 }} />
    </ScrollView>
  </View>;
}

function MoveTray({ actions, active, onChoose }: { actions: { id: EditorId; label: string; icon: keyof typeof Ionicons.glyphMap }[]; active: EditorId | null; onChoose: (id: EditorId) => void }) { return <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.moveTray}>{actions.map((action) => <Pressable key={action.id} onPress={() => onChoose(action.id)} style={[styles.moveButton, active === action.id && styles.moveButtonActive]}><Ionicons name={active === action.id ? 'close' : action.icon} size={15} color={active === action.id ? Colors.black : Colors.primary} /><Text style={[styles.moveButtonText, active === action.id && styles.moveButtonTextActive]}>{active === action.id ? 'Close' : action.label}</Text></Pressable>)}</ScrollView>; }
function EditorCard({ eyebrow, title, children }: { eyebrow: string; title: string; children: React.ReactNode }) { return <View style={styles.editorCard}><Text style={styles.editorEyebrow}>{eyebrow}</Text><Text style={styles.editorTitle}>{title}</Text><View style={styles.editorBody}>{children}</View></View>; }
function ChoiceRail({ values, selected, onSelect }: { values: { id: string; label: string }[]; selected: string; onSelect: (id: string) => void }) { return values.length ? <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.choiceRail}>{values.map((item) => <Pressable key={item.id} onPress={() => onSelect(item.id)} style={[styles.choice, selected === item.id && styles.choiceActive]}><Text style={[styles.choiceText, selected === item.id && styles.choiceTextActive]}>{item.label}</Text></Pressable>)}</ScrollView> : <Text style={styles.editorEmpty}>Nothing is ready to select yet.</Text>; }
function MobileField({ label, value, onChangeText, placeholder, multiline, keyboardType, compact }: { label: string; value: string; onChangeText: (value: string) => void; placeholder?: string; multiline?: boolean; keyboardType?: TextInputProps['keyboardType']; compact?: boolean }) { return <View style={[styles.mobileField, compact && styles.mobileFieldCompact]}><Text style={styles.mobileFieldLabel}>{label}</Text><TextInput value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor={Colors.gray[600]} multiline={multiline} keyboardType={keyboardType} style={[styles.mobileFieldInput, multiline && styles.mobileFieldArea]} /></View>; }
function FormAction({ label, disabled, pending, onPress }: { label: string; disabled?: boolean; pending?: boolean; onPress: () => void }) { return <Pressable accessibilityRole="button" disabled={disabled || pending} onPress={onPress} style={[styles.formAction, (disabled || pending) && styles.disabled]}>{pending ? <ActivityIndicator size="small" color={Colors.black} /> : <><Text style={styles.formActionText}>{label}</Text><Ionicons name="arrow-forward" size={15} color={Colors.black} /></>}</Pressable>; }
function Section({ icon, eyebrow, title, children }: { icon: keyof typeof Ionicons.glyphMap; eyebrow: string; title: string; children: React.ReactNode }) { return <View style={styles.section}><View style={styles.sectionHead}><View style={styles.sectionIcon}><Ionicons name={icon} size={18} color={Colors.primary} /></View><View style={styles.flex}><Text style={styles.sectionEyebrow}>{eyebrow}</Text><Text style={styles.sectionTitle}>{title}</Text></View></View><View style={styles.sectionBody}>{children}</View></View>; }
function Chips({ values = [], empty }: { values?: string[]; empty: string }) { return values.length ? <View style={styles.chips}>{values.map((value) => <View key={value} style={styles.chip}><Text style={styles.chipText}>{value.replaceAll('_', ' ')}</Text></View>)}</View> : <Text style={styles.body}>{empty}</Text>; }
function Return({ label, value }: { label: string; value?: string }) { return <View style={styles.returnBox}><Text style={styles.returnLabel}>{label}</Text><Text style={styles.returnText}>{value || 'Define what this successful experience should open.'}</Text></View>; }
function Info({ label, value }: { label: string; value: string }) { return <View style={styles.info}><Text style={styles.infoLabel}>{label}</Text><Text style={styles.infoValue}>{value}</Text></View>; }
function MiniResult({ value, label }: { value: number; label: string }) { return <View style={styles.miniResult}><Text style={styles.miniValue}>{value}</Text><Text style={styles.miniLabel}>{label}</Text></View>; }
function ReviewLoopCard({ label, question, value }: { label: string; question: string; value?: string }) { return <View style={styles.reviewCard}><Text style={styles.reviewLabel}>{label}</Text><Text style={styles.reviewQuestion}>{question}</Text><Text style={styles.reviewValue}>{value}</Text></View>; }
function ReviewSignal({ label, value }: { label: string; value?: string | null }) { return value ? <View style={styles.reviewCard}><Text style={styles.reviewLabel}>{label}</Text><Text style={styles.reviewValue}>{value}</Text></View> : null; }
function MobileLifecycle({ state, ready, fundingReady, pending, onMove }: { state: string; ready: boolean; fundingReady: boolean; pending: boolean; onMove: (state: string) => void }) { const next: Record<string, [string, string]> = { shaping: ['inviting', 'Invite the people'], inviting: ['awaiting_responses', 'Wait for responses'], awaiting_responses: ['aligned', 'Mark the room aligned'], aligned: ['funding', 'Open funding'], funding: ['funded', 'Confirm secured Gems'], funded: ['live', 'Bring it live'], live: ['completed', 'Complete the Moment'], completed: ['reviewed', ACTIVATION_RETURN_REVIEW.reviewedCta] }; const action = next[state]; if (!action) return <View style={styles.ready}><Ionicons name="rocket" size={20} color={Colors.black} /><View style={styles.readyCopy}><Text style={styles.readyTitle}>The activation is {state}.</Text></View></View>; const blocked = pending || (state === 'shaping' && !ready) || (state === 'funding' && !fundingReady); return <Pressable disabled={blocked} onPress={() => onMove(action[0])} style={[styles.primary, blocked && styles.disabled]}><Ionicons name="rocket" size={16} color={Colors.black} /><Text style={styles.primaryText}>{action[1]}</Text></Pressable>; }

